void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;

    float hash(vec2 p) {
        float h = dot(p, vec2(127.1, 311.7));
        return fract(sin(h) * 43758.5453);
    }

    vec3 color = vec3(0.0);
    float t = iTime * 0.3;

    for(float i = 0.0; i < 5.0; i++) {
        float layer = i / 5.0;
        vec2 p = uv * (2.0 + i * 0.5);
        p.x += sin(t + i * 1.5) * 0.3;
        p.y += cos(t * 0.7 + i) * 0.3;

        vec2 gv = fract(p) - 0.5;
        vec2 id = floor(p);

        float n = hash(id + vec2(i));
        float sparkle = sin(t * 3.0 + n * 6.28318) * 0.5 + 0.5;
        sparkle = pow(sparkle, 10.0);

        float d = length(gv) - 0.05 * (0.5 + sparkle * 0.5);
        float star = smoothstep(0.05, 0.0, d);

        float rays = 0.0;
        for(float j = 0.0; j < 4.0; j++) {
            float angle = j * 3.14159 * 0.5;
            vec2 dir = vec2(cos(angle), sin(angle));
            float ray = abs(dot(gv, dir));
            rays += smoothstep(0.3, 0.0, ray) * smoothstep(0.01, 0.0, abs(dot(gv, vec2(-dir.y, dir.x))));
