        float brightness = star + rays * 0.3 * sparkle;

        vec3 starColor = mix(vec3(0.8, 0.9, 1.0), vec3(1.0, 0.7, 0.9), n);
        starColor = mix(starColor, vec3(1.0, 0.95, 0.7), step(0.8, n));

        color += starColor * brightness * (1.0 - layer * 0.3);
