void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;

    float hash(vec2 p) {
        p = fract(p * vec2(123.34, 456.21));
        p += dot(p, p + 45.32);
        return fract(p.x * p.y);
    }

    float noise(vec2 p) {
        vec2 i = floor(p);
        vec2 f = fract(p);
        f = f * f * (3.0 - 2.0 * f);

        float a = hash(i);
        float b = hash(i + vec2(1.0, 0.0));
        float c = hash(i + vec2(0.0, 1.0));
        float d = hash(i + vec2(1.0, 1.0));

        return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
    }

    float fbm(vec2 p) {
        float value = 0.0;
        float amplitude = 0.5;
        float frequency = 1.0;

        for(int i = 0; i < 6; i++) {
            value += amplitude * noise(p * frequency);
            frequency *= 2.0;
            amplitude *= 0.5;
        }

        return value;
    }

    vec2 p = uv * 2.0;
    p.x += iTime * 0.1;

    float clouds = fbm(p + vec2(iTime * 0.05, 0.0));
    clouds += fbm(p * 2.0 + vec2(iTime * 0.08, iTime * 0.03)) * 0.5;

    vec3 skyColor = vec3(0.4, 0.65, 0.95);
    vec3 cloudColor = vec3(0.95, 0.96, 1.0);

    float cloudMask = smoothstep(0.45, 0.65, clouds);

    vec3 skyGradient = mix(vec3(0.5, 0.7, 1.0), vec3(0.3, 0.5, 0.9), uv.y * 0.5 + 0.5);

    vec3 col = mix(skyGradient, cloudColor, cloudMask);

    fragColor = vec4(col, 1.0);
}

