void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;

    float hash(vec2 p) {
        p = fract(p * vec2(123.34, 456.21));
        p += dot(p, p + 45.32);
        return fract(p.x * p.y);
    }

    vec3 planetPos = vec2(0.0, 0.0);
    float planetRadius = 0.5;
    float distToPlanet = length(uv - planetPos);

    vec3 color = vec3(0.0);

    for(int i = 0; i < 150; i++) {
        vec2 starPos = vec2(hash(vec2(float(i), 0.0)) * 4.0 - 2.0, hash(vec2(float(i), 1.0)) * 4.0 - 2.0);
        float starSize = hash(vec2(float(i), 2.0)) * 0.003 + 0.001;
        float starDist = length(uv - starPos);
        float starBright = hash(vec2(float(i), 3.0)) * 0.5 + 0.5;
        float twinkle = sin(iTime * 3.0 + float(i)) * 0.2 + 0.8;
        if(starDist < starSize) {
            color += vec3(0.8, 0.9, 1.0) * starBright * twinkle;
        }
    }

    if(distToPlanet < planetRadius) {
        vec2 planetUV = (uv - planetPos) / planetRadius;
        float angle = atan(planetUV.y, planetUV.x);
        float radius = length(planetUV);

        float noise1 = sin(angle * 5.0 + radius * 10.0 + iTime * 0.2) * 0.5 + 0.5;
        float noise2 = sin(angle * 3.0 - radius * 7.0 - iTime * 0.15) * 0.5 + 0.5;

        vec3 green = vec3(0.2, 0.7, 0.3);
        vec3 blue = vec3(0.1, 0.4, 0.8);
        vec3 darkGreen = vec3(0.1, 0.4, 0.2);

        color = mix(green, blue, noise1 * 0.6);
        color = mix(color, darkGreen, noise2 * 0.4);

        float light = max(0.0, dot(normalize(vec3(planetUV, sqrt(max(0.0, 1.0 - radius * radius)))), normalize(vec3(1.0, 0.5, 1.0))));
        color *= light * 0.7 + 0.3;
    }

    for(int i = 0; i < 3; i++) {
        float orbitRadius = 0.8 + float(i) * 0.25;
        float orbitSpeed = 0.5 - float(i) * 0.1;
        float orbitAngle = iTime * orbitSpeed + float(i) * 2.1;
        vec2 moonPos = planetPos + vec2(cos(orbitAngle), sin(orbitAngle)) * orbitRadius;
        float moonRadius = 0.08 + float(i) * 0.02;
        float distToMoon = length(uv - moonPos);

        if(distToMoon < moonRadius) {
            vec2 moonUV = (uv - moonPos) / moonRadius;
            float moonDist = length(moonUV);

            vec3 moonColors[3];
            moonColors[0] = vec3(0.9, 0.3, 0.5);
            moonColors[1] = vec3(0.4, 0.6, 0.9);
            moonColors[2] = vec3(0.8, 0.5, 0.2);

            vec3 moonColor = moonColors[i];

            for(int j = 0; j < 20; j++) {
                vec2 craterPos = vec2(hash(vec2(float(i * 20 + j), 10.0)) * 2.0 - 1.0, hash(vec2(float(i * 20 + j), 11.0)) * 2.0 - 1.0);
                float craterSize = hash(vec2(float(i * 20 + j), 12.0)) * 0.2 + 0.1;
                float craterDist = length(moonUV - craterPos);
                if(craterDist < craterSize) {
                    moonColor *= 0.5;
                }
            }

            float moonLight = max(0.0, dot(normalize(vec3(moonUV, sqrt(max(0.0, 1.0 - moonDist * moonDist)))), normalize(vec3(1.0, 0.5, 1.0))));
            color = moonColor * (moonLight * 0.6 + 0.4);
        }
    }

    fragColor = vec4(color, 1.0);
}

