void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;

    float hash(vec2 p) {
        p = fract(p * vec2(234.34, 435.345));
        p += dot(p, p + 34.23);
        return fract(p.x * p.y);
    }

    vec2 center = vec2(0.0, 0.0);
    vec2 toCenter = center - uv;
    float dist = length(toCenter);
    float angle = atan(toCenter.y, toCenter.x);

    float blackHoleRadius = 0.15;
    float eventHorizonGlow = 0.2;

    vec3 col = vec3(0.0);

    if (dist < blackHoleRadius) {
        col = vec3(0.0);
    } else {
        float bendStrength = blackHoleRadius * blackHoleRadius / (dist * dist);
        vec2 bentUV = uv;

        float bendAngle = angle + bendStrength * 3.14159 * 2.0;
        bentUV = center + vec2(cos(bendAngle), sin(bendAngle)) * dist;

        float diskDist = length(vec2(length(bentUV), bentUV.y * 0.3));
        float diskThickness = 0.15;
        float diskInner = 0.2;
        float diskOuter = 0.8;

        if (diskDist > diskInner && diskDist < diskOuter) {
            float diskMask = smoothstep(diskThickness, 0.0, abs(bentUV.y));

            float rotation = iTime * 0.3 / (diskDist + 0.1);
            float spiralAngle = atan(bentUV.y, bentUV.x) + rotation;

            float noise = hash(vec2(diskDist * 10.0, spiralAngle * 5.0 + iTime * 0.1));
            noise += hash(vec2(diskDist * 20.0, spiralAngle * 10.0)) * 0.5;

            float temp = 1.0 - smoothstep(diskInner, diskOuter, diskDist);
            vec3 diskColor = mix(vec3(1.0, 0.3, 0.1), vec3(1.0, 0.8, 0.2), temp);
            diskColor = mix(diskColor, vec3(0.8, 0.1, 0.05), noise);

            col += diskColor * diskMask * (0.5 + noise * 0.5) * temp * 2.0;
        }

        float glowMask = smoothstep(blackHoleRadius + eventHorizonGlow, blackHoleRadius, dist);
        col += vec3(1.0, 0.5, 0.2) * glowMask * 0.5;

        float lensing = smoothstep(1.5, blackHoleRadius, dist) * bendStrength;
        col += vec3(0.3, 0.5, 1.0) * lensing * 0.3;
    }

    col = pow(abs(col), vec3(0.4545));

    fragColor = vec4(col, 1.0);
}

