void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;

    vec3 col = vec3(0.0);

    float t = iTime * 0.3;

    for(float i = 0.0; i < 5.0; i++) {
        vec2 p = uv;

        float angle = t + i * 0.628;
        float s = sin(angle);
        float c = cos(angle);
        p = mat2(c, -s, s, c) * p;

        p.x += sin(t + i * 1.5) * 0.3;
        p.y += cos(t * 0.8 + i * 1.2) * 0.3;

        float helixX = p.x;
        float helixY = sin(p.x * 6.0 + t * 2.0 + i * 6.28 / 5.0) * 0.15;
        float helixZ = cos(p.x * 6.0 + t * 2.0 + i * 6.28 / 5.0) * 0.15;

        vec2 strand1 = vec2(helixX, p.y - helixY);
        vec2 strand2 = vec2(helixX, p.y - helixZ);

        float d1 = length(strand1);
        float d2 = length(strand2);

        float glow1 = 0.01 / (d1 + 0.01);
        float glow2 = 0.01 / (d2 + 0.01);

        vec3 color1 = vec3(0.2, 0.6, 1.0) * glow1;
        vec3 color2 = vec3(1.0, 0.3, 0.5) * glow2;

        float connection = step(abs(helixY - helixZ), 0.05) * step(abs(p.y - helixY), 0.01);
        vec3 connectColor = vec3(0.8, 0.9, 1.0) * connection * 0.3;

        col += color1 + color2 + connectColor;
    }

    float vignette = 1.0 - length(uv * 0.5);
    vignette = smoothstep(0.3, 1.0, vignette);

    col *= vignette;

    col = pow(col, vec3(0.8));

    fragColor = vec4(col, 1.0);
}

