void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;

    float t = iTime * 0.3;
    vec3 color = vec3(0.0);

    for(float i = 0.0; i < 5.0; i++) {
        float layer = i / 5.0;
        vec2 p = uv * (3.0 + i * 0.5);

        float angle = t * (0.5 + layer * 0.3) + layer * 6.28;
        float c = cos(angle);
        float s = sin(angle);
        mat2 rot = mat2(c, -s, s, c);
        p = rot * p;

        vec2 cell = floor(p);
        vec2 local = fract(p) - 0.5;

        float hash1 = fract(sin(dot(cell, vec2(127.1, 311.7))) * 43758.5453);
        float hash2 = fract(sin(dot(cell, vec2(269.5, 183.3))) * 43758.5453);

        float shapeType = hash1;
        float morphTime = t * 0.5 + hash2 * 6.28;
        float morph = sin(morphTime) * 0.5 + 0.5;

        float dist;
        if(shapeType < 0.33) {
            float radius = 0.3 + 0.1 * sin(t * 2.0 + hash2 * 6.28);
            dist = length(local) - radius;
        } else if(shapeType < 0.66) {
            float size = 0.3 + 0.1 * cos(t * 1.5 + hash2 * 6.28);
            dist = max(abs(local.x), abs(local.y)) - size;
        } else {
            float angle2 = atan(local.y, local.x);
            float radius2 = 0.3 + 0.1 * sin(angle2 * 3.0 + t * 2.0);
            dist = length(local) - radius2;
        }

        float edge = smoothstep(0.02, 0.0, abs(dist) - 0.01);
        float fill = smoothstep(0.01, 0.0, dist) * (0.2 + morph * 0.3);

        vec3 hue = vec3(
            sin(t + layer * 2.0 + hash1 * 6.28) * 0.5 + 0.5,
            sin(t * 0.7 + layer * 3.0 + hash2 * 6.28) * 0.5 + 0.5,
            cos(t * 0.9 + layer * 1.5) * 0.5 + 0.5
        );

        color += (edge + fill) * hue * (1.0 - layer * 0.15);
    }

    color = pow(color, vec3(0.8));
    fragColor = vec4(color, 1.0);
}

